import{_ as a,o as t,c as i,a8 as s,a9 as o,aa as n,ab as r,ac as d,ad as l,ae as c,af as m,ag as p,ah as h,ai as g,aj as u,ak as f,al as b,am as y,an as _}from"./chunks/framework.ALLMRHJF.js";const F=JSON.parse('{"title":"User docs","description":"","frontmatter":{},"headers":[],"relativePath":"content/plugins/bcew-document-repository/user-docs.md","filePath":"content/plugins/bcew-document-repository/user-docs.md"}'),x={name:"content/plugins/bcew-document-repository/user-docs.md"};function v(D,e,w,k,P,T){return t(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="user-docs" tabindex="-1">User docs <a class="header-anchor" href="#user-docs" aria-label="Permalink to “User docs”">​</a></h1><p>This guide explains how administrators and authorized users can upload, organize, search, and manage PDF documents and their metadata.</p><h2 id="document-repository" tabindex="-1">Document Repository <a class="header-anchor" href="#document-repository" aria-label="Permalink to “Document Repository”">​</a></h2><p><img src="'+o+'" alt="Document Repository Overview"></p><h3 id="prerequisites-and-access" tabindex="-1">Prerequisites and access <a class="header-anchor" href="#prerequisites-and-access" aria-label="Permalink to “Prerequisites and access”">​</a></h3><ul><li>Document Repository plugin installed and enabled.</li><li>WordPress Search plugin installed and enabled to search document metadata.</li><li>Admins and users with the configured Document Repository capability can upload, edit, and delete documents. The default capability is <code>upload_files</code>.</li></ul><h3 id="where-to-find-it" tabindex="-1">Where to find it <a class="header-anchor" href="#where-to-find-it" aria-label="Permalink to “Where to find it”">​</a></h3><p>In WordPress Admin: <strong>Document Repository</strong> (left navigation).</p><p><img src="'+n+'" alt="Where To Find Document Repository"></p><h3 id="what-you-can-do" tabindex="-1">What you can do <a class="header-anchor" href="#what-you-can-do" aria-label="Permalink to “What you can do”">​</a></h3><ul><li>Upload PDF documents.</li><li>Organize documents with titles and excerpts.</li><li>Add custom metadata fields defined in <strong>Metadata Settings</strong>.</li><li>Search and filter by document content and metadata.</li><li>Use standard list and spreadsheet views.</li></ul><h3 id="upload-a-document" tabindex="-1">Upload a document <a class="header-anchor" href="#upload-a-document" aria-label="Permalink to “Upload a document”">​</a></h3><ol><li>Go to <strong>Document Repository</strong> in WordPress Admin.</li><li>Drag files into the <strong>Drag &amp; Drop</strong> area, or click <strong>Choose Files</strong>.</li><li>Select PDF files and click <strong>Open</strong>.</li><li>Uploaded documents appear in the list.</li></ol><p>Only valid PDF files are accepted.</p><p><img src="'+r+'" alt="Upload a Document"></p><h3 id="edit-document-metadata" tabindex="-1">Edit document metadata <a class="header-anchor" href="#edit-document-metadata" aria-label="Permalink to “Edit document metadata”">​</a></h3><ol><li>Go to <strong>Document Repository</strong>.</li><li>Click the pencil icon to open the editor, or edit inline in <strong>Spreadsheet Mode</strong>.</li><li>Update the <strong>Title</strong>, <strong>Excerpt</strong>, and any <strong>Metadata Fields</strong>.</li><li>Click <strong>Save Changes</strong>.</li></ol><p>Taxonomy fields may contain one or more values, separated by commas or Enter.</p><p><img src="'+d+'" alt="Edit a Document"></p><h3 id="delete-trash-a-document" tabindex="-1">Delete (trash) a document <a class="header-anchor" href="#delete-trash-a-document" aria-label="Permalink to “Delete (trash) a document”">​</a></h3><ol><li>Select documents and click <strong>Trash Selected</strong>, or click the <strong>Trash</strong> icon beside a document.</li><li>Review the confirmation and confirm, or cancel.</li></ol><p>Trashed documents can be restored or permanently deleted from the <strong>Trash</strong> view. Permanent deletion removes the file and associated metadata.</p><p><img src="'+l+'" alt="Delete a Document"></p><h3 id="search-documents" tabindex="-1">Search documents <a class="header-anchor" href="#search-documents" aria-label="Permalink to “Search documents”">​</a></h3><p>Use the <strong>Search</strong> box, enter a keyword, then press <strong>Enter</strong> or click <strong>Search</strong>. Search matches titles, excerpts, and metadata. Clear the input and search again, or click <strong>X</strong>, to reset.</p><p><img src="'+c+'" alt="Search For Documents in the repository"></p><h3 id="view-modes" tabindex="-1">View modes <a class="header-anchor" href="#view-modes" aria-label="Permalink to “View modes”">​</a></h3><p>Standard view shows titles, excerpts, configured metadata, file size and type, revisions, and actions. Spreadsheet view shows documents and metadata in columns and supports inline editing. Use the <strong>View Mode</strong> toggle in the top-right to switch.</p><p><img src="'+m+'" alt="Switch View Modes"></p><h3 id="document-revisions" tabindex="-1">Document revisions <a class="header-anchor" href="#document-revisions" aria-label="Permalink to “Document revisions”">​</a></h3><ol><li>Click <strong>Revisions</strong> for a document.</li><li>Use <strong>Previous</strong> and <strong>Next</strong> to navigate versions.</li><li>Click <strong>Restore this Revision</strong> to apply it; this opens the editor.</li><li>Optionally edit the revision text and save.</li></ol><p><img src="'+p+'" alt="Document Revisions"></p><p>Documents can be <strong>Published</strong>, <strong>Draft</strong>, or <strong>Pending Review</strong>. To restore a trashed document, open <strong>Trash</strong>, select it, and click <strong>Restore</strong>.</p><h3 id="tips-and-troubleshooting" tabindex="-1">Tips and troubleshooting <a class="header-anchor" href="#tips-and-troubleshooting" aria-label="Permalink to “Tips and troubleshooting”">​</a></h3><ul><li>Use descriptive titles and excerpts; define metadata fields before large uploads.</li><li>Confirm files are valid PDFs and within hosting size limits if upload fails.</li><li>If search misses documents, ensure the WordPress Search plugin is active and has indexed metadata.</li><li>If fields do not appear, create them in <strong>Metadata Settings</strong> and refresh.</li><li>Verify user permissions if editing or deleting is unavailable.</li></ul><h2 id="metadata-settings" tabindex="-1">Metadata Settings <a class="header-anchor" href="#metadata-settings" aria-label="Permalink to “Metadata Settings”">​</a></h2><p>Metadata Settings defines custom fields displayed on documents and used for search, sorting, and filtering.</p><p><img src="'+h+'" alt="Metadata Settings Overview"></p><h3 id="access-and-fields" tabindex="-1">Access and fields <a class="header-anchor" href="#access-and-fields" aria-label="Permalink to “Access and fields”">​</a></h3><p>In WordPress Admin, go to <strong>Document Repository → Metadata Settings</strong>. Admins and users with the configured Document Repository capability can manage fields. The default capability is <code>upload_files</code>.</p><p><img src="'+g+'" alt="Where To Find Metadata Settings"></p><p>Each field has a required <strong>Field Label</strong>, a <strong>Field Type</strong> (<code>Text</code>, <code>Date</code>, or <code>Taxonomy</code>), and optional <strong>Description</strong>. Taxonomy fields require terms, one per line; for example, taxonomy Animals with terms Ape, Bear, and Coyote.</p><p><img src="'+u+'" alt="Metadata Field Form"></p><p>Field type cannot be changed after creation. Text and Date values may be empty; Taxonomy requires terms. New fields appear on documents with blank values until edited.</p><h3 id="add-a-field" tabindex="-1">Add a field <a class="header-anchor" href="#add-a-field" aria-label="Permalink to “Add a field”">​</a></h3><ol><li>Go to <strong>Document Repository → Metadata Settings</strong> and click <strong>Add New Field</strong>.</li><li>Enter a label and choose Text, Date, or Taxonomy.</li><li>For Taxonomy, enter terms one per line and optionally enable <strong>Multiple Choice</strong>.</li><li>Optionally add a description, then click <strong>Save</strong>.</li></ol><p><img src="'+f+'" alt="Add Metadata Field"></p><h3 id="edit-or-delete-a-field" tabindex="-1">Edit or delete a field <a class="header-anchor" href="#edit-or-delete-a-field" aria-label="Permalink to “Edit or delete a field”">​</a></h3><p>Click <strong>Edit</strong> beside a field to update its label, description, or taxonomy terms. Type is locked after creation. Keep at least one taxonomy term. Removing a term immediately removes that term assignment from every document that used it; adding a term does not assign it to existing documents.</p><p>Click <strong>Delete</strong> and confirm to permanently remove the field and all its values. The field disappears from both views.</p><p><img src="'+b+'" alt="Edit Metadata Field"><img src="'+y+'" alt="Delete Metadata Field"></p><h3 id="use-metadata" tabindex="-1">Use metadata <a class="header-anchor" href="#use-metadata" aria-label="Permalink to “Use metadata”">​</a></h3><p>Fields appear as columns in standard and spreadsheet views. Edit values per document in either view. Text, date, and taxonomy fields can be searched or filtered by matching text, date, or selected terms.</p><p><img src="'+_+'" alt="Using a Metadata Field"></p><p>Create only fields you will use; plan taxonomy terms carefully. If fields are missing, refresh and confirm they exist and you have permission. New fields are blank until document values are edited. Field types are fixed; delete and recreate a field to change type. Keep the number of fields and taxonomy terms manageable for performance.</p>',55)])])}const R=a(x,[["render",v]]);export{F as __pageData,R as default};
